    def rob(self, nums):
        if len(nums) == 1:
            return nums[0]
        def helper(nums):
            one, two = 0, 0
            for i in nums:
                temp = max(i + one, two)
                one = two
                two = temp
            return two

        return max(helper(nums[:-1]), helper(nums[1:]))

class Solution:
    def rob(self, nums):
        if len(nums) == 0:
            return 0

        if len(nums) == 1:
            return nums[0]

        return max(self.robRange(nums, 0, len(nums) - 1),\
                   self.robRange(nums, 1, len(nums)))

    def robRange(self, nums, start, end):
        num_i, num_i_1 = nums[start], 0
        for i in range(start + 1, end):
            num_i_1, num_i_2 = num_i, num_i_1
            num_i = max(nums[i] + num_i_2, num_i_1)

        return num_i

class Solution:
    def shortestPalindrome(self, s: str) -> str:

        end = 0

        # if the string itself is a palindrome return it
        if(s == s[::-1]):
            return s

        # Otherwise find the end index of the longest palindrome that starts
        # from the first character of the string

        for i in range(len(s)+1):
            if(s[:i]==s[:i][::-1]):
                end=i-1

        # return the string with the remaining characters other than
        # the palindrome reversed and added at the beginning

        return (s[end+1:][::-1])+s

